            new Quote { Id = "https://pt.wikiquote.org/wiki/Monteiro_Lobato", Text = "Tudo é loucura ou sonho no começo. Nada do que o homem fez no mundo teve início de outra maneira — mas já tantos sonhos se realizaram que não temos o direito de duvidar de nenhum.", Author = "Monteiro Lobato" },
